def transform(grid):
    h, w = len(grid), len(grid[0])
    seed = next(((r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == 2), None)
    if seed is None:
        return [row[:] for row in grid]

    # Rotate vertical stripe patterns so the barriers become horizontal
    # and the marker approaches them from the top.
    row_strength = max(sum(v == 8 for v in row) for row in grid)
    col_strength = max(sum(grid[r][c] == 8 for r in range(h)) for c in range(w))
    rotate = None

    if col_strength > row_strength:
        sr, sc = seed
        if sc == 0:
            # clockwise
            g = [[grid[h - 1 - r][c] for r in range(h)] for c in range(w)]
            rotate = "cw"
        else:
            # counterclockwise
            g = [[grid[r][w - 1 - c] for r in range(h)] for c in range(w)]
            rotate = "ccw"
    else:
        g = [row[:] for row in grid]

    H, W = len(g), len(g[0])
    out = [row[:] for row in g]
    sr, sc = next(((r, c) for r in range(H) for c in range(W)
                   if g[r][c] == 2), (0, 0))

    def paint(r, c):
        if 0 <= r < H and 0 <= c < W and out[r][c] == 0:
            out[r][c] = 2

    barriers = [r for r in range(sr + 1, H)
                if sum(v == 8 for v in g[r]) >= W // 2]
    active = {sc}
    previous = sr

    for br in barriers:
        gaps = {c for c, value in enumerate(g[br]) if value == 0}
        if not gaps:
            continue

        for r in range(previous + 1, br):
            for c in active:
                paint(r, c)

        # A single opening connects across the full preceding row.
        if len(gaps) == 1:
            lo, hi = 0, W - 1
        else:
            lo, hi = min(active | gaps), max(active | gaps)
        for c in range(lo, hi + 1):
            paint(br - 1, c)

        for c in gaps:
            paint(br, c)
        active = gaps
        previous = br

    for r in range(previous + 1, H):
        for c in active:
            paint(r, c)

    if rotate == "cw":
        # Inverse clockwise rotation.
        return [[out[c][W - 1 - r] for c in range(H)] for r in range(W)]
    if rotate == "ccw":
        # Inverse counterclockwise rotation.
        return [[out[W - 1 - c][r] for c in range(H)] for r in range(W)]
    return out
